-- Initial schema. Forward-only (no down migrations). IDs are UUID v7,
-- generated by the application. JSON at the API boundary is camelCase;
-- columns here stay snake_case.

create table users (
    id uuid primary key,
    username text not null,
    display_name text not null,
    email text not null,
    password_hash text not null,
    role text not null default 'member' check (role in ('admin', 'moderator', 'member')),
    first_name text,
    last_name text,
    location text,
    website text,
    about_me text,
    language text not null default 'en-US' check (language in ('en-US', 'de')),
    timezone text not null default 'UTC',
    notify_on_reply boolean not null default true,
    notify_on_quote boolean not null default true,
    show_online boolean not null default true,
    post_count integer not null default 0,
    last_seen_at timestamptz,
    created_at timestamptz not null default now()
);

create unique index users_username_lower_idx on users (lower(username));
create unique index users_email_lower_idx on users (lower(email));

create table sessions (
    id uuid primary key,
    user_id uuid not null references users (id) on delete cascade,
    token_hash text not null,
    csrf_token text not null,
    remember boolean not null default false,
    user_agent text,
    ip text,
    expires_at timestamptz not null,
    last_seen_at timestamptz not null default now(),
    created_at timestamptz not null default now()
);

create unique index sessions_token_hash_idx on sessions (token_hash);
create index sessions_user_id_idx on sessions (user_id);
create index sessions_expires_at_idx on sessions (expires_at);

create table categories (
    id uuid primary key,
    name text not null,
    description text not null default '',
    position integer not null,
    admin_only boolean not null default false,
    created_at timestamptz not null default now()
);

create index categories_position_idx on categories (position);

create table boards (
    id uuid primary key,
    category_id uuid not null references categories (id) on delete cascade,
    name text not null,
    description text not null default '',
    position integer not null,
    admin_only boolean not null default false,
    topic_count integer not null default 0,
    post_count integer not null default 0,
    last_post_id uuid,
    created_at timestamptz not null default now()
);

create index boards_category_position_idx on boards (category_id, position);

create table topics (
    id uuid primary key,
    board_id uuid not null references boards (id) on delete cascade,
    title text not null,
    slug text not null,
    author_id uuid not null references users (id) on delete cascade,
    pinned boolean not null default false,
    locked boolean not null default false,
    reply_count integer not null default 0,
    view_count integer not null default 0,
    last_post_id uuid,
    last_post_at timestamptz,
    created_at timestamptz not null default now()
);

create index topics_board_pinned_last_idx on topics (board_id, pinned desc, last_post_at desc nulls last);

create table posts (
    id uuid primary key,
    topic_id uuid not null references topics (id) on delete cascade,
    author_id uuid not null references users (id) on delete cascade,
    body text not null,
    edited_at timestamptz,
    edited_by uuid references users (id) on delete set null,
    created_at timestamptz not null default now()
);

create index posts_topic_created_idx on posts (topic_id, created_at);
create index posts_author_created_idx on posts (author_id, created_at desc);

alter table boards
    add constraint boards_last_post_fk foreign key (last_post_id) references posts (id) on delete set null;
alter table topics
    add constraint topics_last_post_fk foreign key (last_post_id) references posts (id) on delete set null;

create table post_revisions (
    id uuid primary key,
    post_id uuid not null references posts (id) on delete cascade,
    body text not null,
    edited_by uuid references users (id) on delete set null,
    created_at timestamptz not null default now()
);

create index post_revisions_post_idx on post_revisions (post_id, created_at);

create table news_items (
    id uuid primary key,
    title text not null,
    slug text not null,
    body text not null,
    author_id uuid references users (id) on delete set null,
    published_at timestamptz not null default now(),
    created_at timestamptz not null default now()
);

create unique index news_items_slug_idx on news_items (slug);
create index news_items_published_idx on news_items (published_at desc);

create table cms_content (
    key text primary key,
    data jsonb not null,
    updated_at timestamptz not null default now()
);
